const snippets={"Python": ["from typing import Optional", "", "class Solution:", "", "    def isPalindrome(self, head: Optional[ListNode]) -> bool:", "        (slow, fast) = (head, head.next)", "        while fast and fast.next:", "            (slow, fast) = (slow.next, fast.next.next)", "        (pre, cur) = (None, slow.next)", "        while cur:", "            t = cur.next", "            cur.next = pre", "            (pre, cur) = (cur, t)", "        while pre:", "            if pre.val != head.val:", "                return False", "            (pre, head) = (pre.next, head.next)", "        return True"], "Java": ["import java.util.*;", "class Solution {", "    public boolean isPalindrome(ListNode head) {", "        ListNode slow = head;", "        ListNode fast = head.next;", "        while (fast != null && fast.next != null) {", "            slow = slow.next;", "            fast = fast.next.next;", "        }", "        ListNode cur = slow.next;", "        slow.next = null;", "        ListNode pre = null;", "        while (cur != null) {", "            ListNode t = cur.next;", "            cur.next = pre;", "            pre = cur;", "            cur = t;", "        }", "        while (pre != null) {", "            if (pre.val != head.val) {", "                return false;", "            }", "            pre = pre.next;", "            head = head.next;", "        }", "        return true;", "    }", "}"]};
